<script setup>
import {ref} from 'vue'
const props=defineProps({level:{default:1},interactive:Boolean})
const selected=ref('');const selectedId=ref('')
const nodes=[{id:'parent',x:70,y:175,label:'Starting version',detail:'Ask for two changes to the same starting code. Both candidates use the same experiment settings.'},{id:'a',x:270,y:80,label:'Candidate A',detail:'Read Candidate A’s proposed edit to the model, loss, or training code. Its explanation tells you what the agent expects the change to do.'},{id:'b',x:270,y:275,label:'Candidate B',detail:'Read Candidate B’s alternative change to that same starting code. Test it separately so you can compare the outcomes.'},{id:'pa',x:465,y:80,label:'Train + validate A',detail:'Train Candidate A on the training dates, then measure its validation error. Open the saved prediction to see what it missed.'},{id:'pb',x:465,y:275,label:'Train + validate B',detail:'Train Candidate B with the same data and settings. If training fails, inspect its error before deciding what to try next.'},{id:'compose',x:665,y:175,label:'Choose changes',detail:'Give the agent both test results. Ask it to choose a candidate, combine changes, or retain the starting version.'},{id:'test',x:865,y:175,label:'Test composition',detail:'Train and score the chosen code. Keep the previous version if the proposed version does not lower validation error.'},{id:'next',x:1050,y:175,label:'Round 2',detail:'Start round two from the selected code and the lesson saved with it. Continue using the same task and scoring rule.'}]
const visible=n=>n.id==='parent'||(props.level>=1&&['a','b'].includes(n.id))||(props.level>=2&&['pa','pb'].includes(n.id))||(props.level>=3&&n.id==='compose')||(props.level>=4&&n.id==='test')||(props.level>=5&&n.id==='next')
const choose=n=>{if(props.interactive){selected.value=n.detail;selectedId.value=n.id}}
</script>
<template><div class="research-branches"><svg viewBox="0 0 1140 375" :role="interactive?'group':'img'" aria-label="Two proposed code changes train independently, composition reviews their evidence, the composition runs, and a retained version begins round two">
<g fill="none" stroke-width="3"><path v-if="level>=1" d="M70 175C150 175 150 80 270 80" stroke="#4382a6"/><path v-if="level>=1" d="M70 175C150 175 150 275 270 275" stroke="#c17b40"/><path v-if="level>=2" d="M270 80H465" stroke="#4382a6"/><path v-if="level>=2" d="M270 275H465" stroke="#c17b40"/><path v-if="level>=3" d="M465 80C570 80 565 175 665 175M465 275C570 275 565 175 665 175" stroke="#638382" stroke-dasharray="7 6"/><path v-if="level>=4" d="M665 175H865" stroke="#163c43"/><path v-if="level>=5" d="M865 175H1050" stroke="#163c43"/></g>
<g v-for="n in nodes.filter(visible)" :key="n.id" class="node" :tabindex="interactive?0:-1" :role="interactive?'button':undefined" :aria-label="n.label" :aria-pressed="interactive?selectedId===n.id:undefined" @click="choose(n)" @keydown.enter="choose(n)" @keydown.space.prevent="choose(n)"><rect :x="n.x-90" :y="n.y-20" width="180" height="90" fill="transparent" pointer-events="all"/><circle :cx="n.x" :cy="n.y" r="15" :stroke="selectedId===n.id?'#f1ca70':'none'" stroke-width="5" :fill="['a','pa'].includes(n.id)?'#4382a6':['b','pb'].includes(n.id)?'#c17b40':n.id==='compose'?'#f1ca70':'#163c43'"/><text :x="n.x" :y="n.y+48" text-anchor="middle">{{n.label}}</text><text v-if="n.id==='compose'" :x="n.x" :y="n.y+72" text-anchor="middle" class="small">keep, combine, or retain</text></g>
</svg><div v-if="interactive" class="branch-detail" aria-live="polite">{{selected||'Select a step to see what code or result passes to the next one.'}}</div><div class="legend"><span>Solid line: code moves to the next step</span><span>Dashed line: test results are reviewed</span><span>Color identifies the candidate</span></div></div></template>
<style scoped>svg{width:100%;height:335px}text{font:20px 'IBM Plex Sans';fill:#163c43}.small{font-size:15px}.node[role=button]{cursor:pointer}.node:focus{outline:3px solid #f1ca70}</style>
